def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # If we defected last round and opponent cooperated, they are not retaliating; defect always.
    if n >= 1 and history[-1][0] == 'D' and history[-1][1] == 'C':
        return 'D'

    # If opponent defected in the first round, defect always.
    if n >= 1 and history[0][1] == 'D':
        return 'D'

    # If opponent has been extremely defective overall, defect always.
    opp_def_total = sum(1 for _, o in history if o == 'D')
    if n >= 5 and opp_def_total / n > 0.8:
        return 'D'

    # Endgame
    if n >= 99:
        return 'D'
    if n == 98:
        recent_def = any(history[i][1] == 'D' for i in range(max(0, n-3), n))
        if recent_def:
            return 'D'
        else:
            return 'C'

    # Anti-exploitation mode (AEM) based on first 10 rounds
    if n >= 10:
        first10_opp_def = sum(1 for i in range(10) if history[i][1] == 'D')
        if first10_opp_def >= 3:
            if n >= 96:
                return 'D'
            last_my_def_idx = -1
            for i in range(n-1, -1, -1):
                if history[i][0] == 'D':
                    last_my_def_idx = i
                    break
            if last_my_def_idx == -1 or n - last_my_def_idx > 9:
                return 'D'
            else:
                return 'C'

    # Tit-for-two-tats: defect if opponent defected last two rounds
    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    return 'C'
